@startuml

class Customer {
  + name : string
  + dateOfBirth : date
  + address : string
  + taxCode : string
}

class Broker {
  + brokerId : int
  + name : string
  + contactInfo : string
}

class Contract {
  + contractId : int
  + signingDate : date
  + insuredAmount : double
  + policyType : PolicyType
  + status : ContractStatus
}

abstract class Policy {
  + policyId : int
  + description : string
}

class LifePolicy {}
class CarLiabilityPolicy {}
class TheftPolicy {}

class Claim {
  + claimId : int
  + dateOfOccurrence : date
  + amountClaimed : double
  + status : ClaimStatus
}

class Estimator {
  + estimatorId : int
  + name : string
  + expertiseArea : ExpertiseArea
}

enum PolicyType { Life, CarLiability, Theft }
enum ContractStatus { Pending, Approved, Declined }
enum ClaimStatus { Open, UnderReview, Approved, Paid }
enum ExpertiseArea { MaterialDamage, PhysicalDamage }

Customer "1" -- "1..*" Broker
Broker "1" -- "0..*" Customer
Customer "1" -- "1..*" Contract
Contract "1" -- "1" Policy
Policy "1" -- "0..*" LifePolicy
Policy "1" -- "0..*" CarLiabilityPolicy
Policy "1" -- "0..*" TheftPolicy
Broker "1" -- "0..*" Claim
Claim "1" -- "0..*" Estimator

@enduml

